using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using PowerShapeGeometry;

namespace PowerShapeBridge {
 // Internal qualification executor; no production COM adapter or MCP/queue route.
 internal static class OwnedGeometryExport {
  internal interface IContext : DocumentBindings.IContext {
   Dictionary<string,object> ExportSettings();
   int Composite(int type,int id);
   void AddSelection(int type,int id,string name);
   void ExportDmt(string fixedPath);
   void ClearOwnSelection();
  }
  static void Require(bool ok,string error){if(!ok)throw new InvalidDataException(error);}
  static Dictionary<string,object> Clone(Dictionary<string,object> value){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(value));}
  internal static void Validate(Dictionary<string,object> args){Require(args.Count==2&&args.ContainsKey("targetId")&&EntitySets.Hex(args["targetId"],32)&&args.ContainsKey("targetSha256")&&EntitySets.Hex(args["targetSha256"],64),"Exact export target ID/SHA required.");}
  internal static void QuotedPath(string path){OwnedCopies.LocalPath(path);Require(path.Length<260&&path.All(c=>c>=32&&c<127&&(char.IsLetterOrDigit(c)||" :\\/_.-".Contains(c))),"Fixed quoted ASCII export path without command delimiters required.");}
  internal static void Settings(Dictionary<string,object> value) {
   string[] fields={"translator","triangulationToleranceRaw","solidShading","limitTriangleEdgeLength","maximumTriangleEdgeLengthRaw","toleranceLengthUnits","providerQualification"};
   Require(value.Count==fields.Length&&fields.All(value.ContainsKey)&&Equals(value["translator"],"built_in_local")&&Equals(value["toleranceLengthUnits"],"document_raw")&&value["solidShading"] is bool&&value["limitTriangleEdgeLength"] is bool&&value["providerQualification"] is string&&!string.IsNullOrWhiteSpace((string)value["providerQualification"]),"Exact observed DMT settings required.");
   Positive(value["triangulationToleranceRaw"]);if((bool)value["limitTriangleEdgeLength"])Positive(value["maximumTriangleEdgeLengthRaw"]);else Require(value["maximumTriangleEdgeLengthRaw"]==null,"Disabled edge limit must have null effective length.");
  }
  static void Positive(object value){Require(value is int||value is long||value is double||value is float||value is decimal,"Numeric DMT tolerance required.");double number=Program.StrictDouble(value);Require(!double.IsNaN(number)&&!double.IsInfinity(number)&&number>0&&number<=1000000,"Finite bounded positive DMT tolerance required.");}
  static Dictionary<string,object>[] Targets(OwnedGeometryExportTargets.Dependencies source,IContext context) {
   var inventory=EntitySets.Inventory(source.Expected);var targets=new List<Dictionary<string,object>>();
   foreach(var key in source.Keys) {
    var entity=inventory.Single(e=>Equals(e["nativeTypeCode"],key[0])&&Equals(e["nativeId"],key[1]));string type=key[0]==40?"SOLID":"SURFACE";object raw;Require(entity.TryGetValue("name",out raw)&&raw is string&&!string.IsNullOrWhiteSpace((string)raw),"Observed native name required.");string name=(string)raw;Require(!name.Any(c=>char.IsControl(c)||c=='\''),"Native name cannot be safely selected.");Require(Equals(entity["type"],type)&&inventory.Count(e=>Equals(e["type"],type)&&Equals(e["name"],name))==1,"Type/name selection is ambiguous.");
    Require(entity.ContainsKey("levelNumber")&&entity["levelNumber"] is int,"Observed target level required.");var levels=(source.Expected["levelsContainingEntities"] as IList);Require(levels!=null,"Observed levels required.");var active=levels.Cast<Dictionary<string,object>>().Where(l=>Equals(l["number"],entity["levelNumber"])).ToArray();Require(active.Length==1&&(Equals(active[0]["activeRaw"],1)||Equals(active[0]["activeRaw"],true)),"Target level must already be active; no implicit level activation.");
    targets.Add(new Dictionary<string,object>{{"entityKey",key},{"type",type},{"name",name},{"levelNumber",entity["levelNumber"]},{"compositeId",context.Composite(key[0],key[1])}});
   }
   Require(targets.Select(t=>t["compositeId"]).Distinct().Count()==targets.Count&&targets.All(t=>t["compositeId"] is int&&(int)t["compositeId"]>0),"Direct item mapping absent/ambiguous.");return targets.ToArray();
  }
  static void Check(OwnedGeometryExportTargets.TargetLease lease,IContext context,Dictionary<string,object>[] targets,int selected,Dictionary<string,object> settings,Dictionary<string,string> saved) {
   lease.RecheckDependencies();var expected=targets.Take(selected).Select(t=>new Dictionary<string,object>{{"type",t["type"]},{"name",t["name"]}}).ToArray();
   for(int pass=0;pass<2;pass++) {
    var fresh=context.Observation();foreach(string key in new[]{"contextBefore","contextAfter"})Require(EntitySets.Canonical(fresh[key])==EntitySets.Canonical(new[]{selected,0}),"Selection count/world frame changed.");foreach(string key in new[]{"selectionBefore","selectionAfter"})Require(EntitySets.Canonical(fresh[key])==EntitySets.Canonical(expected),"Exact owned selection differs.");
    var normalized=Clone(fresh);normalized["contextBefore"]=normalized["contextAfter"]=new[]{0,0};normalized["selectionBefore"]=normalized["selectionAfter"]=new object[0];EntitySets.CheckObserved(lease.Source.Expected,normalized,lease.Source.Keys,lease.Source.Expires,DateTime.UtcNow);
    var observed=context.ExportSettings();Settings(observed);Require(EntitySets.Canonical(observed)==EntitySets.Canonical(settings),"Pinned DMT settings changed.");
    foreach(var target in targets){var key=EntitySets.Keys(new[]{target["entityKey"]}).Single();Require(Equals(context.Composite(key[0],key[1]),target["compositeId"]),"Selection target mapping changed.");}
   }
   context.ConfirmDocument();var windows=context.Windows();Require(DocumentBindings.WindowDigest(windows)==(string)lease.Plan["windowContextSha256"]&&DateTime.UtcNow<lease.Source.Expires,"Export document/windows/lifetime changed.");lease.Copy.CheckPath((string)((Dictionary<string,object>)lease.Source.Expected["model"])["path"]);lease.Copy.Recheck();var current=WorkingCopyOpen.SavedHashes(windows);Require(saved.Count==current.Count&&saved.All(pair=>current.ContainsKey(pair.Key)&&current[pair.Key]==pair.Value),"Saved documents changed during export.");
  }
  static string Event(string folder,int index,string phase,object value){return NativeJournal.Freeze(Path.Combine(folder,index.ToString("D6")+"."+phase+".json"),value);}
  internal static Dictionary<string,object> Execute(string root,string id,Dictionary<string,object> args,IContext context) {
   var result=new Dictionary<string,object>{{"state","owned_geometry_export_rejected_before_change"},{"operationId",id},{"exportAttempted",false},{"contextChangeAttempted",false},{"geometryMutationAttempted",false},{"cadSaveAttempted",false},{"geometryVerified",false},{"retryAllowed",false},{"copyFenceReleased",false},{"nativeProviderQualified",false}};NativeJournal journal=null;int calls=0;string fence=null;Dictionary<string,object> sourceProof=null;
   try {
    Validate(args);Require(EntitySets.Hex(id,32),"Export execution ID required.");
    using(var serial=new FileStream(Path.Combine(root,"operations","executor.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))using(var lease=new OwnedGeometryExportTargets.TargetLease(root,(string)args["targetId"],(string)args["targetSha256"]))using(var proofs=new OwnedOperationPlans.Proofs()) {
     sourceProof=new Dictionary<string,object>{{"requestId",lease.Plan["inspectionRequestId"]},{"sha256",lease.Plan["inspectionSha256"]}};
     var settings=Clone(context.ExportSettings());Settings(settings);var targets=Targets(lease.Source,context);var saved=WorkingCopyOpen.SavedHashes(context.Windows());Check(lease,context,targets,0,settings,saved);lease.Recheck();string targetPath=(string)lease.Plan["targetPath"];QuotedPath(targetPath);
     var plan=new Dictionary<string,object>(args){{"schemaVersion",1},{"operationId",id},{"operation","export_owned_geometry"},{"copyId",lease.Plan["copyId"]},{"ownershipSha256",lease.Plan["ownershipSha256"]},{"workingSha256",lease.Plan["workingSha256"]},{"targetPath",targetPath},{"targets",targets},{"settings",settings},{"windowContextSha256",lease.Plan["windowContextSha256"]},{"savedFileHashesBefore",saved},{"createdUtc",DateTime.UtcNow.ToString("o")},{"qualification","Internal callback executor; native export/selection/settings and mesh coordinate convention unqualified"}};
     string executionFolder=Path.Combine(root,"geometryexportexecutions");Directory.CreateDirectory(executionFolder);OwnedCopies.NoReparse(executionFolder);string sha=NativeJournal.Freeze(Path.Combine(executionFolder,id+".json"),plan);result["planSha256"]=sha;result["plan"]=plan;result["copyId"]=plan["copyId"];result["localArtifactsMayExist"]=true;
     journal=new NativeJournal(root,id,sha);journal.Append("prepared",new Dictionary<string,object>{{"operation","export_owned_geometry"},{"targetCount",targets.Length}});fence=OwnedGeometryExportTargets.ExportFencePath(root,(string)plan["copyId"]);string fenceSha=NativeJournal.Freeze(fence,new Dictionary<string,object>{{"schemaVersion",1},{"operationId",id},{"planSha256",sha},{"copyId",plan["copyId"]},{"ownershipSha256",plan["ownershipSha256"]},{"automaticReplayForbidden",true}});proofs.Json(fence,fenceSha);result["exportFenceSha256"]=fenceSha;
     string commandFolder=OwnedGeometryExportTargets.Folder(root,(string)args["targetId"]);string claimSha=NativeJournal.Freeze(Path.Combine(commandFolder,"export-once.json"),new Dictionary<string,object>{{"operationId",id},{"planSha256",sha},{"targetId",args["targetId"]},{"automaticReplayForbidden",true}});proofs.Json(Path.Combine(commandFolder,"export-once.json"),claimSha);journal.Append("execution_claimed",new Dictionary<string,object>{{"targetId",args["targetId"]},{"automaticReplayForbidden",true}});Check(lease,context,targets,0,settings,saved);
     var records=new List<Dictionary<string,object>>();journal.Append("command_started",new Dictionary<string,object>{{"selectionAndExport",true},{"targetCount",targets.Length}});
     for(int index=0;index<targets.Length;index++) {
      var item=targets[index];string started=Event(commandFolder,index,"started",new{operationId=id,planSha256=sha,index=index,kind="add_selection",target=item});Check(lease,context,targets,index,settings,saved);Require(!File.Exists(targetPath)&&!Directory.Exists(targetPath),"Export result appeared before selection.");var key=EntitySets.Keys(new[]{item["entityKey"]}).Single();calls++;result["contextChangeAttempted"]=true;context.AddSelection(key[0],key[1],(string)item["name"]);string returned=Event(commandFolder,index,"returned",new{operationId=id,planSha256=sha,index=index,kind="add_selection",startedSha256=started,callbackReturned=true});records.Add(new Dictionary<string,object>{{"kind","add_selection"},{"index",index},{"startedSha256",started},{"returnedSha256",returned}});Check(lease,context,targets,index+1,settings,saved);
     }
     int exportIndex=targets.Length;string exportStart=Event(commandFolder,exportIndex,"started",new{operationId=id,planSha256=sha,index=exportIndex,kind="export_dmt",path=targetPath});Check(lease,context,targets,targets.Length,settings,saved);Require(!File.Exists(targetPath)&&!Directory.Exists(targetPath),"Export result collision after publication.");calls++;result["exportAttempted"]=true;context.ExportDmt(targetPath);string exportReturn=Event(commandFolder,exportIndex,"returned",new{operationId=id,planSha256=sha,index=exportIndex,kind="export_dmt",startedSha256=exportStart,callbackReturned=true});records.Add(new Dictionary<string,object>{{"kind","export_dmt"},{"index",exportIndex},{"startedSha256",exportStart},{"returnedSha256",exportReturn}});Check(lease,context,targets,targets.Length,settings,saved);
     OwnedCopies.NoReparse(targetPath);using(var output=new FileStream(targetPath,FileMode.Open,FileAccess.Read,FileShare.Read)) {
      var identity=OwnedCopies.FileIdentity(output,targetPath,true);var mesh=DmtMeshReader.Read(output);string outputSha=OwnedCopies.Digest(output);Require(EntitySets.Canonical(identity)==EntitySets.Canonical(OwnedCopies.FileIdentity(output,targetPath,true))&&OwnedCopies.Digest(output)==outputSha,"Export bytes/identity changed.");result["outputSha256"]=outputSha;result["meshParsed"]=true;result["meshLengthUnits"]=mesh.LengthUnits;result["meshCoordinateFrame"]="file_coordinates_unqualified";result["triangleCount"]=mesh.TriangleCount;result["vertexCount"]=mesh.VertexCount;
      int clearIndex=targets.Length+1;string clearStart=Event(commandFolder,clearIndex,"started",new{operationId=id,planSha256=sha,index=clearIndex,kind="clear_own_selection"});Check(lease,context,targets,targets.Length,settings,saved);calls++;context.ClearOwnSelection();string clearReturn=Event(commandFolder,clearIndex,"returned",new{operationId=id,planSha256=sha,index=clearIndex,kind="clear_own_selection",startedSha256=clearStart,callbackReturned=true});records.Add(new Dictionary<string,object>{{"kind","clear_own_selection"},{"index",clearIndex},{"startedSha256",clearStart},{"returnedSha256",clearReturn}});Check(lease,context,targets,0,settings,saved);Require(OwnedCopies.Digest(output)==outputSha,"Export changed after selection restore.");
      journal.Append("command_returned",new Dictionary<string,object>{{"callbackCalls",calls},{"exportCallbackReturned",true},{"nativeReturnCodeQualified",false}});string summary=NativeJournal.Freeze(Path.Combine(commandFolder,"export-summary.json"),new{operationId=id,planSha256=sha,commands=records,outputSha256=outputSha,outputFileIdentity=identity,meshParsed=true,geometryVerified=false});journal.Append("executed_unverified",new Dictionary<string,object>{{"summarySha256",summary},{"independentVerificationRequired",true}});result["summarySha256"]=summary;result["state"]="owned_geometry_export_executed_unverified";result["selectionRestoredObserved"]=true;
     }
    }
   }catch(Exception error){result["error"]=error.Message;bool unknown=calls>0||journal!=null&&journal.State=="command_started";result["state"]=unknown?"owned_geometry_export_outcome_unknown":"owned_geometry_export_rejected_before_change";if(journal!=null)try{if(new[]{"prepared","execution_claimed"}.Contains(journal.State))journal.Append("rejected_before_change",new Dictionary<string,object>{{"contextChangeAttempted",false},{"evidence",new[]{sourceProof}}});else if(new[]{"command_started","command_returned"}.Contains(journal.State))journal.Append("outcome_unknown",new Dictionary<string,object>{{"callbackCallsAttempted",calls},{"error",error.Message}});}catch(Exception failure){result["journalError"]=failure.Message;}}
   result["callbackCallsAttempted"]=calls;result["copyExportFenced"]=fence==null?(object)null:File.Exists(fence);if(journal!=null)result["recordedJournalState"]=journal.State;result["timestampUtc"]=DateTime.UtcNow.ToString("o");return result;
  }
 }
}
